import{_ as t}from"./chunks/daily-2026-08-10-serialized-tool-lifecycle-authority-figure.CKmgEQfX.js";import{_ as n,C as o,o as i,c as r,E as s,a2 as l}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Tool Runtimes Need Serialized Lifecycle Authority","description":"","frontmatter":{"title":"Tool Runtimes Need Serialized Lifecycle Authority","date":"2026-08-10","column":"open-source-engineering","category":"daily","summary":"Shared tool and connector runtimes should serialize connect, reconnect and cleanup under one lifecycle authority, keep cleanup accountable across caller cancellation, bound waits and preserve failed teardown as governance state before a new generation is allowed to start.","sources":["research/analysis/Q-20260810-03-serialized-lifecycle-governance.md","research/reading/Q-20260810-03-mcp-lifecycle-serialization.md"],"item_id":"Q-20260810-03","lifecycle":"Published","source_research_object":"research/analysis/Q-20260810-03-serialized-lifecycle-governance.md","source_reading_result":"research/reading/Q-20260810-03-mcp-lifecycle-serialization.md","cover":"/assets/covers/daily-2026-08-10-serialized-tool-lifecycle-authority.webp","visualization":"/assets/covers/daily-2026-08-10-serialized-tool-lifecycle-authority-figure.svg","visualization_decision":"Required — dedicated editorial Article Cover passes Cover Gate; explanatory Article Figure retained separately","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"en/engineering/2026-08-10-serialized-tool-lifecycle-authority.md","filePath":"en/engineering/2026-08-10-serialized-tool-lifecycle-authority.md","lastUpdated":1786455299000}'),c={name:"en/engineering/2026-08-10-serialized-tool-lifecycle-authority.md"};function d(u,e,p,h,m,y){const a=o("ArticleCover");return i(),r("div",null,[s(a,{image:"/assets/covers/daily-2026-08-10-serialized-tool-lifecycle-authority.webp",kicker:"Open-source Engineering · Daily Research",title:"Tool Runtimes Need Serialized Lifecycle Authority",summary:"Shared tool and connector runtimes should serialize connect, reconnect and cleanup under one lifecycle authority, keep cleanup accountable across caller cancellation, bound waits and preserve failed teardown as governance state before a new generation is allowed to start.",version:"Q-20260810-03",status:"Daily Runtime V5 · 2026-08-10",languageHref:"/zh/engineering/2026-08-10-serialized-tool-lifecycle-authority",languageLabel:"中文"}),e[0]||(e[0]=l('<h1 id="tool-runtimes-need-serialized-lifecycle-authority" tabindex="-1">Tool Runtimes Need Serialized Lifecycle Authority <a class="header-anchor" href="#tool-runtimes-need-serialized-lifecycle-authority" aria-label="Permalink to &quot;Tool Runtimes Need Serialized Lifecycle Authority&quot;">​</a></h1><p>Connect, reconnect and cleanup look like ordinary helper methods until multiple callers operate on the same tool runtime. At that point they become control-plane transitions: they mutate shared resource state, determine which generation owns the connection, and decide whether teardown has finished safely enough for replacement.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p><strong>The central judgment is that shared tool runtimes need one serialized lifecycle authority per managed resource domain.</strong> Cleanup ownership should survive an initiating caller&#39;s cancellation when resource safety requires completion, waits should be bounded, cleanup failures should remain observable, and a replacement generation should not begin until the previous generation is confirmed stopped or explicitly force-recovered by policy.</p><p>The completed Reading Result examines a merged OpenAI Agents Python fix for <code>MCPServerManager</code>. It is concrete engineering evidence for manager-local lifecycle serialization and cancellation-safe cleanup ownership. It is not evidence for distributed locking across processes or hosts.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>Production consumes the same-day Research Object <code>Q-20260810-03</code> and uses its completed Reading Result only to verify citations and implementation boundaries. Primary evidence comes from OpenAI Agents Python issue #4334, merged PR #4340 and commit <code>7da5696020a82d7ee2546a557eb8990169e23815</code>.</p><ul><li>Issue: <a href="https://github.com/openai/openai-agents-python/issues/4334" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/issues/4334</a></li><li>Merged PR: <a href="https://github.com/openai/openai-agents-python/pull/4340" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/pull/4340</a></li><li>Implementation commit: <a href="https://github.com/openai/openai-agents-python/commit/7da5696020a82d7ee2546a557eb8990169e23815" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/commit/7da5696020a82d7ee2546a557eb8990169e23815</a></li></ul><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>Before the fix, public lifecycle operations could overlap while sharing manager and worker state. Commands could be queued after cleanup even though the relevant worker had already exited, leaving unresolved futures and inconsistent state.</p><p>The merged repair introduces one manager-level lifecycle lock above public <code>connect_all()</code>, <code>reconnect()</code> and <code>cleanup_all()</code> transitions. Parallel cleanup is represented by one cleanup future and awaited through <code>asyncio.shield</code>, so cancellation of a caller does not automatically cancel the underlying cleanup operation. A stopping worker is awaited before replacement, cleanup failures are retained, and connect/cleanup operations use finite 10-second defaults unless the application explicitly opts out.</p><p><img src="'+t+'" alt="Serialized lifecycle authority figure"></p><p><em>Figure 1. Connect, Reconnect, and Cleanup share one serialized lifecycle authority; a new Generation cannot start before the previous one closes. Source: Research Center synthesis based on the cited primary sources.</em></p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lifecycle model</th><th>Transition ownership</th><th>Cancellation behavior</th><th>Wait boundary</th><th>Failed cleanup handling</th><th>Replacement safety</th></tr></thead><tbody><tr><td>Independently callable lifecycle methods</td><td>Competing callers</td><td>Caller cancellation can interrupt coordination</td><td>Undefined by ordering alone</td><td>Easy to lose in races</td><td>New work may overlap teardown</td></tr><tr><td>Per-server worker queue only</td><td>Per worker, not manager-wide</td><td>Task affinity preserved</td><td>Queue-local</td><td>Does not prevent manager races</td><td>Insufficient for overlapping public transitions</td></tr><tr><td>Manager-level serialized lifecycle</td><td>One lock orders public transitions</td><td>Cleanup future can outlive caller cancellation</td><td>Connect/cleanup defaults finite</td><td>Failure remains observable</td><td>Stopping worker must finish before replacement</td></tr><tr><td>Governed multi-process lifecycle</td><td>Research Center proposal: lease/fencing authority per resource domain</td><td>Ownership survives caller/session boundaries by policy</td><td>Lock, operation and recovery deadlines separated</td><td>Failure becomes quarantine/recovery state</td><td>New generation requires fencing token and explicit policy</td></tr></tbody></table><p>The first three rows summarize mechanisms documented by the issue, PR, commit and Reading Result. The final row is a Research Center engineering proposal for systems that extend beyond one in-process manager.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>A mutex alone is not enough. Serialization converts unsafe overlap into ordered waiting, but a protected operation that can wait forever merely turns races into queue stalls. Lifecycle governance therefore needs both a single transition authority and explicit time budgets.</p><p>Cancellation also needs a resource-centric interpretation. A caller disappearing does not prove that teardown is complete. If cleanup owns sockets, subprocesses, browser sessions or external leases, abandoning cleanup with the caller can leave the next generation operating against partially torn-down resources.</p><p>Finally, cleanup failure should not be overwritten by a convenient “clean” state. Preserving terminal teardown errors creates an explicit safety decision: quarantine, restart, operator approval or force replacement. Fabricating a clean state merely to reconnect destroys the evidence needed to govern the transition.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>For Digital Employees, treat browser sessions, MCP connections, credential sessions and other external-tool runtimes as managed resources with lifecycle owner, generation id, timeout, cleanup status and recovery policy. Two workflow branches should not independently reconnect or tear down the same resource.</p><p>For CodeFlowMu, place a per-resource lifecycle mutex or lease above adapter-specific workers, persist lifecycle transitions in the operation log, keep finite connect/cleanup deadlines by default, and expose wait duration, timeout, retained cleanup failure and generation replacement events.</p><p>When multiple processes can address the same external resource, add fencing or generation tokens; a process-local lock is no longer enough.</p><p>For TMPA, the merged implementation is useful engineering evidence for bounded ownership transitions, but one library fix is not sufficient to define protocol-level lifecycle semantics.</p><h2 id="boundaries-and-uncertainty" tabindex="-1">Boundaries and uncertainty <a class="header-anchor" href="#boundaries-and-uncertainty" aria-label="Permalink to &quot;Boundaries and uncertainty&quot;">​</a></h2><p>The evidence is manager-local. It does not coordinate replicas across hosts. Applications can explicitly set lifecycle timeouts to <code>None</code>, removing the finite operation deadline. The regression suite uses controlled fake servers and therefore cannot cover every subprocess, transport, shutdown or OS-level failure. The <code>suppress_cancelled_error</code> policy also changes what a cancelled caller observes and must be understood by applications.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>The next design questions are whether lifecycle lock acquisition needs a deadline distinct from connect/cleanup deadlines; how generation fencing should work across processes; which cleanup failures require quarantine, process restart, human approval or force replacement; and which telemetry should expose lock wait, stopping state, cleanup timeout and retained errors.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The header cover uses controlled, sequential resource chambers to represent serialized lifecycle authority. The explanatory figure embedded in the Observation section shows the relationship among connect, reconnect and cleanup. The two visual roles use different assets; no vendor artwork or invented quantitative data is used.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>OpenAI <code>openai-agents-python</code> Issue #4334, lifecycle overlap race reproduction: <a href="https://github.com/openai/openai-agents-python/issues/4334" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/issues/4334</a></li><li>OpenAI <code>openai-agents-python</code> PR #4340, merged lifecycle serialization fix: <a href="https://github.com/openai/openai-agents-python/pull/4340" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/pull/4340</a></li><li>OpenAI <code>openai-agents-python</code> commit <code>7da5696020a82d7ee2546a557eb8990169e23815</code>: <a href="https://github.com/openai/openai-agents-python/commit/7da5696020a82d7ee2546a557eb8990169e23815" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python/commit/7da5696020a82d7ee2546a557eb8990169e23815</a></li><li>Research Center Research Object: <code>research/analysis/Q-20260810-03-serialized-lifecycle-governance.md</code></li><li>Research Center Reading Result: <code>research/reading/Q-20260810-03-mcp-lifecycle-serialization.md</code></li></ol><blockquote><p>Editing status: published. Manager-local scope, cancellation semantics, timeout boundary, preserved cleanup failure, bilingual structure and evidence traceability checked.</p></blockquote>',34))])}const v=n(c,[["render",d]]);export{b as __pageData,v as default};
